{"command":"cat << 'EOF' > src/style.rs
use serde::Deserialize;

#[derive(Debug, Clone, PartialEq, Default, Deserialize)]
#[serde(default)]
pub struct Style {
    pub fg: Option<String>,
    pub bg: Option<String>,
    pub bold: Option<bool>,
    pub faint: Option<bool>,
    pub dim: Option<bool>,
    pub italic: Option<bool>,
    pub underline: Option<bool>,
}

impl Style {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn fg(mut self, color: &str) -> Self {
        self.fg = Some(color.to_string());
        self
    }

    pub fn bg(mut self, color: &str) -> Self {
        self.bg = Some(color.to_string());
        self
    }

    pub fn bold(mut self) -> Self {
        self.bold = Some(true);
        self
    }

    pub fn faint(mut self) -> Self {
        self.faint = Some(true);
        self
    }

    pub fn italic(mut self) -> Self {
        self.italic = Some(true);
        self
    }

    pub fn underline(mut self) -> Self {
        self.underline = Some(true);
        self
    }

    pub fn to_ansi(&self) -> String {
        let mut codes = Vec::new();

        if self.bold.unwrap_or(false) {
            codes.push("1");
        }
        if self.faint.unwrap_or(false) || self.dim.unwrap_or(false) {
            codes.push("2");
        }
        if self.italic.unwrap_or(false) {
            codes.push("3");
        }
        if self.underline.unwrap_or(false) {
            codes.push("4");
        }

        if let Some(ref bg) = self.bg {
            if let Some(code) = color_to_bg_code(bg) {
                codes.push(code);
            }
        }

        if let Some(ref fg) = self.fg {
            if let Some(code) = color_to_fg_code(fg) {
                codes.push(code);
            }
        }

        if codes.is_empty() {
            String::new()
        } else {
            format!("\x1b[{}m", codes.join(";"))
        }
    }
}

pub fn color_to_fg_code(color: &str) -> Option<&'static str> {
    match color.to_lowercase().as_str() {
        "black" => Some("30"),
        "red" => Some("31"),
        "green" => Some("32"),
        "yellow" => Some("33"),
        "blue" => Some("34"),
        "magenta" => Some("35"),
        "cyan" => Some("36"),
        "white" => Some("37"),
        _ => None,
    }
}

pub fn color_to_bg_code(color: &str) -> Option<&'static str> {
    match color.to_lowercase().as_str() {
        "black" => Some("40"),
        "red" => Some("41"),
        "green" => Some("42"),
        "yellow" => Some("43"),
        "blue" => Some("44"),
        "magenta" => Some("45"),
        "cyan" => Some("46"),
        "white" => Some("47"),
        _ => None,
    }
}
EOF
"}

