            HighlighterGroup::IpAddresses,
            HighlighterGroup::Dates,
            HighlighterGroup::KeyValuePairs,
            HighlighterGroup::Processes,
            HighlighterGroup::Json,
            HighlighterGroup::Numbers,
        ];

        let enabled_groups = if let Some(enabled) = enable_opt {
            let mut res = Vec::new();
            for g_str in enabled {
                if let Some(g) = HighlighterGroup::from_str(g_str) {
                    if !res.contains(&g) {
                        res.push(g);
                    }
                }
            }
            res
        } else if let Some(disabled) = disable_opt {
            let disabled_groups: Vec<HighlighterGroup> = disabled
                .iter()
                .filter_map(|s| HighlighterGroup::from_str(s))
                .collect();
            all_groups
                .into_iter()
                .filter(|g| !disabled_groups.contains(g))
                .collect()
        } else {
            all_groups
        };

        Self {
            enabled_groups,
            enable_builtin_keywords: !disable_builtin_keywords,
            custom_highlights,
            theme,
        }
    }

    pub fn highlight_line(&self, line: &str) -> String {
        let mut spans: Vec<Span> = Vec::new();

        // 1. Highlighters run in sequence, claiming spans
        for group in &self.enabled_groups {
            match group {
                HighlighterGroup::Quotes => quotes::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Urls => urls::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Paths => paths::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Pointers => pointers::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Uuids => uuids::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::IpAddresses => ip::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Dates => dates::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::KeyValuePairs => key_value::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Processes => processes::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Json => json::highlight(line, &self.theme, &mut spans),
                HighlighterGroup::Numbers => numbers::highlight(line, &self.theme, &mut spans),
            }
        }

        // Keywords
        keywords::highlight(line, self.enable_builtin_keywords, &self.theme, &mut spans);

        // Custom highlights (--highlight)
        custom::highlight(line, &self.custom_highlights, &mut spans);

        // Render spans
        render_line(line, &spans)
    }
}

pub fn is_range_available(spans: &[Span], start: usize, end: usize) -> bool {
    for s in spans {
        if start < s.end && end > s.start {
            return false;
        }
    }
    true
}

pub fn add_span_if_available(spans: &mut Vec<Span>, start: usize, end: usize, style_ansi: String) {
    if start < end && is_range_available(spans, start, end) {
        spans.push(Span {
            start,
            end,
            style_ansi,
        });
    }
}

fn render_line(line: &str, spans: &[Span]) -> String {
    if spans.is_empty() {
        return line.to_string();
    }

    // Sort spans by start
    let mut sorted_spans = spans.to_vec();
    sorted_spans.sort_by_key(|s| s.start);

    // Build events
    struct Event {
        pos: usize,
        is_end: bool,
        ansi: String,
    }

    let mut events = Vec::new();
    for s in &sorted_spans {
        events.push(Event {
            pos: s.start,
            is_end: false,
            ansi: s.style_ansi.clone(),
        });
        events.push(Event {
            pos: s.end,
            is_end: true,
            ansi: "\x1b[0m".to_string(),
        });
    }

    // Sort events by position. If positions are equal, ends come before starts.
    events.sort_by(|a, b| {
        if a.pos != b.pos {
            a.pos.cmp(&b.pos)
        } else {
            b.is_end.cmp(&a.is_end)
        }
    });

    let mut res = String::new();
    let mut last_pos = 0;

    for ev in events {
        if ev.pos > last_pos {
            res.push_str(&line[last_pos..ev.pos]);
            last_pos = ev.pos;
        }
        res.push_str(&ev.ansi);
    }

    if last_pos < line.len() {
        res.push_str(&line[last_pos..]);
    }

    res
}
EOF
"}

