use crate::style::Style;
use crate::highlighters::{add_span_if_available, is_range_available, Span};
use regex::Regex;
use once_cell::sync::Lazy;

static JSON_KEY_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r#""([a-zA-Z0-9_.-]+)"\s*:"#).unwrap()
});

static JSON_PUNCT_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"[\{\}\[\],]").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let dim_style = theme
        .json
        .as_ref()
        .and_then(|j| j.key.clone())
        .unwrap_or_else(|| Style::new().faint());

    let dim_ansi = dim_style.to_ansi();
    if dim_ansi.is_empty() {
        return;
    }

    for cap in JSON_KEY_RE.captures_iter(line) {
        if let Some(m_full) = cap.get(0) {
            add_span_if_available(spans, m_full.start(), m_full.end(), dim_ansi.clone());
        }
    }

    for m in JSON_PUNCT_RE.find_iter(line) {
        add_span_if_available(spans, m.start(), m.end(), dim_ansi.clone());
    }
}
EOF
