});

static SEV_GREEN_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(DEBUG|GET)\b").unwrap()
});

static SEV_BLUE_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bPUT\b").unwrap()
