use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static NUM_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"(?<![a-zA-Z0-9_.-])[-+]?\d+(?:\.\d+)?\b").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let style = theme
        .numbers
        .as_ref()
        .and_then(|n| n.number.clone())
        .unwrap_or_else(|| Style::new().fg("cyan"));

    let ansi = style.to_ansi();
    if ansi.is_empty() {
        return;
    }

    for m_res in NUM_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), ansi.clone());
        }
    }
}
