use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, is_range_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static UUID_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let digit_style = theme
        .uuids
        .as_ref()
        .and_then(|u| u.number.clone())
        .unwrap_or_else(|| Style::new().italic().fg("blue"));

    let letter_style = Style::new().italic().fg("magenta");

    let dash_style = theme
        .uuids
        .as_ref()
        .and_then(|u| u.dash.clone())
        .unwrap_or_else(|| Style::new().fg("red"));

    let digit_ansi = digit_style.to_ansi();
    let letter_ansi = letter_style.to_ansi();
    let dash_ansi = dash_style.to_ansi();

    for m_res in UUID_RE.find_iter(line) {
        if let Ok(m) = m_res {
            if is_range_available(spans, m.start(), m.end()) {
                let matched = m.as_str();
                for (i, c) in matched.char_indices() {
                    let start = m.start() + i;
                    let end = start + c.len_utf8();
                    if c.is_ascii_digit() {
                        add_span_if_available(spans, start, end, digit_ansi.clone());
                    } else if c.is_ascii_hexdigit() {
                        add_span_if_available(spans, start, end, letter_ansi.clone());
                    } else if c == '-' {
                        add_span_if_available(spans, start, end, dash_ansi.clone());
                    }
                }
            }
        }
    }
}
EOF
