use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, is_range_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static PROC_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"(?<=^|\s)([a-zA-Z0-9_.-]+|\([a-zA-Z0-9_.-]+\))\[([0-9]+)\]:").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let name_style = theme
        .processes
        .as_ref()
        .and_then(|p| p.name.clone())
        .unwrap_or_else(|| Style::new().fg("yellow"));

    let bracket_style = theme
        .processes
        .as_ref()
        .and_then(|p| p.bracket.clone())
        .unwrap_or_else(|| Style::new().fg("red"));

    let pid_style = Style::new().fg("cyan");

    let name_ansi = name_style.to_ansi();
    let bracket_ansi = bracket_style.to_ansi();
    let pid_ansi = pid_style.to_ansi();

    for cap_res in PROC_RE.captures_iter(line) {
        if let Ok(cap) = cap_res {
            if let (Some(m_full), Some(m_name), Some(m_pid)) = (cap.get(0), cap.get(1), cap.get(2)) {
                if is_range_available(spans, m_full.start(), m_full.end()) {
                    add_span_if_available(spans, m_name.start(), m_name.end(), name_ansi.clone());
                    add_span_if_available(spans, m_name.end(), m_pid.start(), bracket_ansi.clone());
                    add_span_if_available(spans, m_pid.start(), m_pid.end(), pid_ansi.clone());
                    add_span_if_available(spans, m_pid.end(), m_pid.end() + 1, bracket_ansi.clone());
                }
            }
        }
    }
}
