{"command":"cat << 'EOF' > src/highlighters/urls.rs
use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, is_range_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static URL_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(https?)://([a-zA-Z0-9.-]+)(/[^\s?#]*)?(?:\?([^\s#]*))?").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let http_style = theme
        .urls
        .as_ref()
        .and_then(|u| u.http.clone())
        .unwrap_or_else(|| Style::new().faint().fg("red"));

    let https_style = theme
        .urls
        .as_ref()
        .and_then(|u| u.https.clone())
        .unwrap_or_else(|| Style::new().faint().fg("green"));

    let host_style = theme
        .urls
        .as_ref()
        .and_then(|u| u.host.clone())
        .unwrap_or_else(|| Style::new().faint().fg("blue"));

    let path_style = theme
        .urls
        .as_ref()
        .and_then(|u| u.path.clone())
        .unwrap_or_else(|| Style::new().fg("blue"));

    let sep_style = Style::new().fg("red");
    let key_style = Style::new().fg("magenta");
    let val_style = Style::new().fg("cyan");

    let http_ansi = http_style.to_ansi();
    let https_ansi = https_style.to_ansi();
    let host_ansi = host_style.to_ansi();
    let path_ansi = path_style.to_ansi();
    let sep_ansi = sep_style.to_ansi();
    let key_ansi = key_style.to_ansi();
    let val_ansi = val_style.to_ansi();

    for cap_res in URL_RE.captures_iter(line) {
        if let Ok(cap) = cap_res {
            if let Some(m_full) = cap.get(0) {
                if is_range_available(spans, m_full.start(), m_full.end()) {
                    if let Some(m_scheme) = cap.get(1) {
                        let ansi = if m_scheme.as_str() == "https" {
                            &https_ansi
                        } else {
                            &http_ansi
                        };
                        add_span_if_available(spans, m_scheme.start(), m_scheme.end(), ansi.clone());
                    }

                    if let Some(m_host) = cap.get(2) {
                        add_span_if_available(spans, m_host.start(), m_host.end(), host_ansi.clone());
                    }

                    if let Some(m_path) = cap.get(3) {
                        add_span_if_available(spans, m_path.start(), m_path.end(), path_ansi.clone());
                    }

                    if let Some(m_query) = cap.get(4) {
                        let q_start = m_query.start() - 1;
