use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static BOOL_NULL_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(true|false|null|nil|none)\b").unwrap()
});

static SEV_WHITE_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bINFO\b").unwrap()
});

static SEV_YELLOW_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(WARN|WARNING|POST)\b").unwrap()
});

static SEV_RED_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(ERROR|FATAL|FAIL|CRITICAL|SEVERE|DELETE)\b").unwrap()
});

static SEV_GREEN_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(DEBUG|GET)\b").unwrap()
});

static SEV_BLUE_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bPUT\b").unwrap()
});

static SEV_CYAN_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bPATCH\b").unwrap()
});

static SEV_MAGENTA_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(HEAD|OPTIONS|CONNECT)\b").unwrap()
});

static SEV_DIM_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bTRACE\b").unwrap()
});

pub fn highlight(line: &str, enable_builtin: bool, theme: &ThemeToml, spans: &mut Vec<Span>) {
    // Custom keywords from TOML config
    if let Some(ref custom_kw) = theme.keywords {
        for kw in custom_kw {
            let ansi = kw.style.to_ansi();
            if ansi.is_empty() {
                continue;
            }
            for word in &kw.words {
                if word.is_empty() {
                    continue;
                }
                if let Ok(re) = Regex::new(&format!(r"\b{}\b", regex::escape(word))) {
                    for m_res in re.find_iter(line) {
                        if let Ok(m) = m_res {
                            add_span_if_available(spans, m.start(), m.end(), ansi.clone());
                        }
                    }
                }
            }
        }
    }

    if !enable_builtin {
        return;
    }

    let bool_ansi = Style::new().italic().fg("red").to_ansi();
    for m_res in BOOL_NULL_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), bool_ansi.clone());
        }
    }

    let white_ansi = Style::new().fg("white").to_ansi();
    for m_res in SEV_WHITE_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), white_ansi.clone());
        }
    }

    let yellow_ansi = Style::new().fg("yellow").to_ansi();
    for m_res in SEV_YELLOW_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), yellow_ansi.clone());
        }
    }

    let red_ansi = Style::new().fg("red").to_ansi();
    for m_res in SEV_RED_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), red_ansi.clone());
        }
    }

    let green_ansi = Style::new().fg("green").to_ansi();
    for m_res in SEV_GREEN_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), green_ansi.clone());
        }
    }

    let blue_ansi = Style::new().fg("blue").to_ansi();
    for m_res in SEV_BLUE_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), blue_ansi.clone());
        }
    }

    let cyan_ansi = Style::new().fg("cyan").to_ansi();
    for m_res in SEV_CYAN_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), cyan_ansi.clone());
        }
    }

    let magenta_ansi = Style::new().fg("magenta").to_ansi();
    for m_res in SEV_MAGENTA_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), magenta_ansi.clone());
