        .dates
        .as_ref()
        .and_then(|d| d.zone.clone())
        .unwrap_or_else(|| Style::new().fg("red"));

    let sep_style = theme
        .dates
        .as_ref()
        .and_then(|d| d.separator.clone())
        .unwrap_or_else(|| Style::new().faint());

    let date_ansi = date_style.to_ansi();
    let time_ansi = time_style.to_ansi();
    let zone_ansi = zone_style.to_ansi();
    let sep_ansi = sep_style.to_ansi();

