        .ip_addresses
        .as_ref()
        .and_then(|ip| ip.separator.clone())
        .unwrap_or_else(|| Style::new().fg("red"));

    let letter_style = Style::new().italic().fg("magenta");

    let digit_ansi = digit_style.to_ansi();
    let sep_ansi = sep_style.to_ansi();
    let letter_ansi = letter_style.to_ansi();

    for m_res in IPV4_RE.find_iter(line) {
        if let Ok(m) = m_res {
            if is_range_available(spans, m.start(), m.end()) {
                let matched = m.as_str();
                let match_start = m.start();
                let mut token_start = 0;
                let mut is_sep = false;

                for (idx, c) in matched.char_indices() {
                    let cur_sep = c == '.';
                    if idx == 0 {
                        is_sep = cur_sep;
                    } else if cur_sep != is_sep {
                        let ansi = if is_sep { &sep_ansi } else { &digit_ansi };
                        if !ansi.is_empty() {
                            add_span_if_available(spans, match_start + token_start, match_start + idx, ansi.clone());
                        }
                        token_start = idx;
                        is_sep = cur_sep;
                    }
                }
                let ansi = if is_sep { &sep_ansi } else { &digit_ansi };
                if !ansi.is_empty() {
                    add_span_if_available(spans, match_start + token_start, match_start + matched.len(), ansi.clone());
                }
            }
        }
    }

    for m_res in IPV6_RE.find_iter(line) {
        if let Ok(m) = m_res {
            if is_range_available(spans, m.start(), m.end()) {
                let matched = m.as_str();
                let match_start = m.start();
                let mut token_start = 0;
                let mut current_type: Option<&str> = None;

                for (idx, c) in matched.char_indices() {
                    let c_type = if c == ':' {
                        "sep"
                    } else if c.is_ascii_digit() {
                        "digit"
                    } else {
                        "letter"
                    };

                    if Some(c_type) != current_type {
                        if let Some(ct) = current_type {
                            let ansi = match ct {
                                "sep" => &sep_ansi,
                                "digit" => &digit_ansi,
                                "letter" => &letter_ansi,
                                _ => "",
                            };
                            if !ansi.is_empty() {
                                add_span_if_available(spans, match_start + token_start, match_start + idx, ansi.to_string());
                            }
                        }
                        token_start = idx;
                        current_type = Some(c_type);
                    }
                }

                if let Some(ct) = current_type {
                    let ansi = match ct {
                        "sep" => &sep_ansi,
                        "digit" => &digit_ansi,
                        "letter" => &letter_ansi,
                        _ => "",
                    };
                    if !ansi.is_empty() {
                        add_span_if_available(spans, match_start + token_start, match_start + matched.len(), ansi.to_string());
                    }
                }
            }
        }
    }
}
