use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static BOOL_NULL_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(true|false|null|nil|none)\b").unwrap()
});

static SEV_WHITE_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bINFO\b").unwrap()
});

static SEV_YELLOW_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(WARN|WARNING)\b").unwrap()
});

static SEV_RED_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\b(ERROR|FATAL|FAIL|CRITICAL|SEVERE)\b").unwrap()
});

static SEV_GREEN_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bDEBUG\b").unwrap()
});

static SEV_DIM_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"\bTRACE\b").unwrap()
});

// REST verbs
static REST_GET_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bGET\b").unwrap());
static REST_POST_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPOST\b").unwrap());
static REST_PUT_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPUT\b").unwrap());
static REST_DELETE_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bDELETE\b").unwrap());
static REST_PATCH_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\bPATCH\b").unwrap());
static REST_HEAD_RE: Lazy<Regex> = Lazy::new(|| Regex::new(r"\b(HEAD|OPTIONS|CONNECT)\b").unwrap());

pub fn highlight(line: &str, enable_builtin: bool, theme: &ThemeToml, spans: &mut Vec<Span>) {
    if let Some(ref custom_kw) = theme.keywords {
        for kw in custom_kw {
            let ansi = kw.style.to_ansi();
            if ansi.is_empty() {
                continue;
            }
            for word in &kw.words {
                if word.is_empty() {
                    continue;
                }
                if let Ok(re) = Regex::new(&format!(r"\b{}\b", regex::escape(word))) {
                    for m_res in re.find_iter(line) {
                        if let Ok(m) = m_res {
                            add_span_if_available(spans, m.start(), m.end(), ansi.clone());
                        }
                    }
                }
            }
        }
    }

    if !enable_builtin {
        return;
    }

    // Booleans & Nulls
    let bool_ansi = Style::new().italic().fg("red").to_ansi();
    for m_res in BOOL_NULL_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), bool_ansi.clone());
        }
    }

    // Severities
    let white_ansi = Style::new().fg("white").to_ansi();
    for m_res in SEV_WHITE_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), white_ansi.clone());
        }
    }

    let yellow_ansi = Style::new().fg("yellow").to_ansi();
    for m_res in SEV_YELLOW_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), yellow_ansi.clone());
        }
    }

    let red_ansi = Style::new().fg("red").to_ansi();
    for m_res in SEV_RED_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), red_ansi.clone());
        }
    }

    let green_ansi = Style::new().fg("green").to_ansi();
    for m_res in SEV_GREEN_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), green_ansi.clone());
        }
    }

    let dim_ansi = Style::new().faint().to_ansi();
    for m_res in SEV_DIM_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), dim_ansi.clone());
        }
    }

    // REST Verbs with padding spaces
    let get_ansi = format!("{} GET \x1b[0m", Style::new().bg("green").fg("black").to_ansi());
    for m_res in REST_GET_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), get_ansi.clone());
        }
    }

    let post_ansi = format!("{} POST \x1b[0m", Style::new().bg("yellow").fg("black").to_ansi());
    for m_res in REST_POST_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), post_ansi.clone());
        }
    }

    let put_ansi = format!("{} PUT \x1b[0m", Style::new().bg("blue").fg("black").to_ansi());
    for m_res in REST_PUT_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), put_ansi.clone());
        }
    }

    let del_ansi = format!("{} DELETE \x1b[0m", Style::new().bg("red").fg("black").to_ansi());
    for m_res in REST_DELETE_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), del_ansi.clone());
        }
    }

    let patch_ansi = format!("{} PATCH \x1b[0m", Style::new().bg("cyan").fg("black").to_ansi());
    for m_res in REST_PATCH_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), patch_ansi.clone());
        }
    }

    let head_ansi = format!("{} HEAD \x1b[0m", Style::new().bg("magenta").fg("black").to_ansi());
    for m_res in REST_HEAD_RE.find_iter(line) {
        if let Ok(m) = m_res {
            add_span_if_available(spans, m.start(), m.end(), head_ansi.clone());
        }
    }
}
EOF
"}

