use crate::config::ThemeToml;
use crate::style::Style;
use crate::highlighters::{add_span_if_available, is_range_available, Span};
use fancy_regex::Regex;
use once_cell::sync::Lazy;

static KV_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r#"(?:^|(?<=\s))([a-zA-Z0-9_.-]+)=("[^"]*"|\S+)"#).unwrap()
});

static INNER_KV_RE: Lazy<Regex> = Lazy::new(|| {
    Regex::new(r"([a-zA-Z0-9_.-]+)=").unwrap()
});

pub fn highlight(line: &str, theme: &ThemeToml, spans: &mut Vec<Span>) {
    let key_style = theme
        .key_value_pairs
        .as_ref()
        .and_then(|kv| kv.key.clone())
        .unwrap_or_else(|| Style::new().faint());

    let sep_style = theme
        .key_value_pairs
        .as_ref()
        .and_then(|kv| kv.separator.clone())
        .unwrap_or_else(|| Style::new().fg("white"));

    let quote_style = theme
        .quotes
        .as_ref()
        .and_then(|q| q.style.clone())
        .unwrap_or_else(|| Style::new().fg("yellow"));

    let key_ansi = key_style.to_ansi();
    let sep_ansi = sep_style.to_ansi();
    let quote_ansi = quote_style.to_ansi();

    for cap_res in KV_RE.captures_iter(line) {
        if let Ok(cap) = cap_res {
            if let (Some(m_full), Some(m_key), Some(m_val)) = (cap.get(0), cap.get(1), cap.get(2)) {
                if is_range_available(spans, m_full.start(), m_full.end()) {
                    add_span_if_available(spans, m_full.start(), m_full.end(), "".to_string());

                    if !key_ansi.is_empty() {
                        add_span_if_available(spans, m_key.start(), m_key.end(), key_ansi.clone());
                    }
                    if !sep_ansi.is_empty() {
                        add_span_if_available(spans, m_key.end(), m_val.start(), sep_ansi.clone());
                    }

                    let val_str = m_val.as_str();
                    let val_start = m_val.start();

                    let has_inner_kv = val_str.contains("=");
                    if has_inner_kv {
                        for inner_cap in INNER_KV_RE.captures_iter(val_str) {
                            if let Ok(icap) = inner_cap {
                                if let (Some(im_full), Some(im_key)) = (icap.get(0), icap.get(1)) {
                                    if !key_ansi.is_empty() {
                                        add_span_if_available(spans, val_start + im_key.start(), val_start + im_key.end(), key_ansi.clone());
                                    }
                                    if !sep_ansi.is_empty() {
                                        add_span_if_available(spans, val_start + im_key.end(), val_start + im_full.end(), sep_ansi.clone());
                                    }
                                }
                            }
                        }
                    } else if val_str.starts_with('"') && val_str.ends_with('"') {
                        if !quote_ansi.is_empty() {
                            add_span_if_available(spans, m_val.start(), m_val.end(), quote_ansi.clone());
                        }
                    }
                }
            }
        }
    }
}
