fn render_line(line: &str, spans: &[Span]) -> String {
    if spans.is_empty() {
        return line.to_string();
    }

    let mut sorted_spans = spans.to_vec();

    sorted_spans.retain(|s| !s.style_ansi.is_empty() || s.end_ansi != "\x1b[0m");
    if sorted_spans.is_empty() {
        return line.to_string();
    }

    sorted_spans.sort_by(|a, b| {
        if a.start != b.start {
            a.start.cmp(&b.start)
        } else {
            b.end.cmp(&a.end)
        }
    });

    struct Event {
        pos: usize,
        is_end: bool,
        idx: usize,
    }

    let mut events = Vec::new();
    for (idx, s) in sorted_spans.iter().enumerate() {
        events.push(Event {
            pos: s.start,
            is_end: false,
            idx,
        });
        events.push(Event {
            pos: s.end,
            is_end: true,
            idx,
        });
    }

    events.sort_by(|a, b| {
        if a.pos != b.pos {
            a.pos.cmp(&b.pos)
        } else {
            a.is_end.cmp(&b.is_end).reverse()
        }
    });

    let mut active_stack: Vec<usize> = Vec::new();
    let mut res = String::new();
    let mut last_pos = 0;

    for ev in events {
        if ev.pos > last_pos {
            res.push_str(&line[last_pos..ev.pos]);
            last_pos = ev.pos;
        }

        if !ev.is_end {
            active_stack.push(ev.idx);
            res.push_str(&sorted_spans[ev.idx].style_ansi);
        } else {
            if let Some(pos) = active_stack.iter().rposition(|&x| x == ev.idx) {
                active_stack.remove(pos);
            }
            res.push_str(&sorted_spans[ev.idx].end_ansi);
            if let Some(&top_idx) = active_stack.last() {
                res.push_str(&sorted_spans[top_idx].style_ansi);
            }
        }
    }

    if last_pos < line.len() {
        res.push_str(&line[last_pos..]);
    }

    res
}
EOF
"}

